-- ============================================================================
-- Seed: Central Park Residential Project construction schedule -> Site Ops
-- Activity Timeline (construction_activities), extracted from
-- "1. Central Park  Construction Schedule R1.xlsx" (RCC Work + Masonry/Plaster
-- Work sheets), C:\Users\karan\Downloads\Pramukh-group\DPR.
--
-- Each schedule stage becomes one activity per building group (B & C / A & D),
-- since the two groups run on independent timelines in the source schedule.
-- Idempotent: skipped entirely if this project already has activities, so
-- re-running the migration (or applying it twice) never duplicates rows.
-- ============================================================================

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.construction_activities WHERE project_id = '00000000-0000-0000-0000-000000000001' LIMIT 1
  ) THEN
    ;
  END IF;
END $$;

-- ============================================================================
-- END OF MIGRATION
-- ============================================================================
